#!/usr/bin/env python3
"""Generate Wirestack's compact ASCII PSL lookup tables from the vendored snapshot."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import unicodedata
from pathlib import Path

HERE = Path(__file__).resolve().parent
INPUT = HERE / "public_suffix_list.dat"
METADATA = HERE / "source.json"
VERSION_PATTERN = re.compile(r"^// VERSION: (\S+)$", re.MULTILINE)
COMMIT_PATTERN = re.compile(r"^// COMMIT: ([0-9a-f]{40})$", re.MULTILINE)


def parse_snapshot(raw: bytes) -> tuple[str, str, list[str], list[str], list[str]]:
    text = raw.decode("utf-8")
    version_match = VERSION_PATTERN.search(text)
    commit_match = COMMIT_PATTERN.search(text)
    if version_match is None or commit_match is None:
        raise ValueError("PSL snapshot lacks pinned VERSION or COMMIT metadata")

    exact: set[str] = set()
    wildcard: set[str] = set()
    exception: set[str] = set()
    for source_line in text.splitlines():
        rule = source_line.strip()
        if not rule or rule.startswith("//"):
            continue
        rule = rule.split(maxsplit=1)[0]
        target = exact
        if rule.startswith("!"):
            target = exception
            rule = rule[1:]
        elif rule.startswith("*."):
            target = wildcard
            rule = rule[2:]
        labels = []
        for label in rule.split("."):
            normalized = unicodedata.normalize("NFC", label.lower())
            ascii_label = (
                normalized if normalized.isascii()
                else "xn--" + normalized.encode("punycode").decode("ascii")
            )
            if re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", ascii_label) is None:
                raise ValueError(f"rule has an invalid DNS label: {source_line!r}")
            labels.append(ascii_label)
        ascii_rule = ".".join(labels)
        if len(ascii_rule) > 253:
            raise ValueError(f"rule exceeds the DNS name bound: {source_line!r}")
        target.add(ascii_rule)
    return (
        version_match.group(1),
        commit_match.group(1),
        sorted(exact),
        sorted(wildcard),
        sorted(exception),
    )


def cangjie_string(value: str) -> str:
    return f'        "{value}"'


def packed_table(name: str, rules: list[str]) -> str:
    packed = "".join(rules)
    offsets = [0]
    for rule in rules:
        offsets.append(offsets[-1] + len(rule))
    offset_lines = [
        "        " + ", ".join(str(value) for value in offsets[index:index + 16])
        for index in range(0, len(offsets), 16)
    ]
    return (
        f"internal let COOKIE_PSL_{name} = CookiePslTable(\n"
        "    (\n"
        f"{cangjie_string(packed)}\n"
        "    ).toArray(),\n"
        "    [\n"
        + ",\n".join(offset_lines)
        + "\n    ]\n"
        ")\n"
    )


def generated_source(version: str, revision: str, digest: str,
                     exact: list[str], wildcard: list[str], exception: list[str]) -> str:
    return (
        "// Generated by third_party/public_suffix/generate.py; do not edit.\n"
        "// Source Code Form derived from publicsuffix/list is governed by MPL-2.0.\n"
        f"// PSL version: {version}\n"
        f"// PSL revision: {revision}\n"
        f"// Snapshot SHA-256: {digest}\n"
        f"// Rules: exact={len(exact)}, wildcard={len(wildcard)}, exception={len(exception)}\n"
        "package wirestack.http\n\n"
        + packed_table("EXACT", exact)
        + "\n"
        + packed_table("WILDCARD", wildcard)
        + "\n"
        + packed_table("EXCEPTION", exception)
    )


def read_metadata() -> dict[str, object]:
    return json.loads(METADATA.read_text(encoding="utf-8"))


def update_metadata(metadata: dict[str, object], version: str, revision: str, digest: str) -> None:
    metadata["upstream_revision"] = revision
    metadata["version"] = version
    metadata["sha256"] = digest
    METADATA.write_text(json.dumps(metadata, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="fail unless metadata and generated data are current")
    parser.add_argument(
        "--update", action="store_true",
        help="refresh pinned metadata from the already-vendored input, then regenerate",
    )
    args = parser.parse_args()
    if args.check and args.update:
        parser.error("--check and --update are mutually exclusive")

    raw = INPUT.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    version, revision, exact, wildcard, exception = parse_snapshot(raw)
    metadata = read_metadata()
    if (
        metadata.get("license") != "MPL-2.0"
        or metadata.get("license_file") != "LICENSE.MPL-2.0"
        or metadata.get("license_sha256")
        != hashlib.sha256((HERE / "LICENSE.MPL-2.0").read_bytes()).hexdigest()
    ):
        raise SystemExit("vendored MPL license does not match source.json")
    if args.update:
        update_metadata(metadata, version, revision, digest)
    else:
        expected = (metadata.get("version"), metadata.get("upstream_revision"), metadata.get("sha256"))
        actual = (version, revision, digest)
        if expected != actual:
            raise SystemExit(
                "vendored PSL does not match source.json; use --update after reviewing the new snapshot"
            )

    generated_paths = metadata.get("generated")
    if not isinstance(generated_paths, list) or generated_paths != ["../../src/http/public_suffix_data.cj"]:
        raise SystemExit("source.json generated paths do not match the generator contract")
    output = (HERE / generated_paths[0]).resolve()
    content = generated_source(version, revision, digest, exact, wildcard, exception)
    if args.check:
        if not output.exists() or output.read_text(encoding="utf-8") != content:
            raise SystemExit(f"generated PSL data is stale: {output}")
        return 0
    output.write_text(content, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
